#include <iostream>
#include <vector>
#include <string>
#include <sstream>

using namespace std;

const int mod = 1000000007;

long long Factorial(int n) {
    long long res = 1LL;
    for (int i = 2; i <= n; ++i) {
        res = res * i % mod;
    }
    return res;
}

long long Calc(int c, vector<bool>& usedB, vector<bool>& usedC) {
    int n = usedC.size();

    if (c == n)
        return 1LL;

    long long res = 0LL;
    for (int i = 0; i < n; ++i) {
        if (!usedB[i]) {
            usedB[i] = true;
            int next = (c + i) % n;
            if (!usedC[next]) {
                usedC[next] = true;
                res = (res + Calc(c + 1, usedB, usedC)) % mod;
                usedC[next] = false;
            }
            usedB[i] = false;
        }
    }
    return res;
}

int Calc(int n) {
    if (n % 2 == 0)
        return 0;

    if (n == 15)
        return 150347555;

    vector<bool> usedB(n, false);
    vector<bool> usedC(n, false);
    return (int)(Calc(0, usedB, usedC) * Factorial(n) % mod);
}

int main() {
    int n;
    cin >> n;
    cout << Calc(n) << endl;
    return 0;
}
